 </div>
 <div className={"cc-validation-item" + (d6Valid ? " cc-validation-item--pass" : " cc-validation-item--fail")}>
 <span className="cc-validation-icon">{d6Valid ? "✓" : "✗"}</span>
 <span>d6 assigned: {d6Valid ? d6Attr : "None"}</span>
 </div>
 </div>
 <div className={"cc-validation-status" + (allValid ? " cc-validation-status--ready" : "")}>
 {allValid ? "[ SYSTEM READY — ALL CHECKS PASSED ]" : "[ AWAITING VALID CONFIGURATION ]"}
 </div>
 </section>
 );
}

function DiceRoller() {
 var [attrDie, setAttrDie] = useState("d8");
 var [diffDie, setDiffDie] = useState("d6");
 var [result, setResult] = useState(null);
 var [rolling, setRolling] = useState(false);

 function handleRoll() {
 setRolling(true);
 setResult(null);
 callAjax("BlackLedgerDice", "ajaxResolveCheck", {
 sysparm_attribute_die: attrDie,
 sysparm_difficulty_die: diffDie
 }).then(function (answer) {
 try {
 setResult(JSON.parse(answer));
 } catch (e) {
 setResult({ error: "Failed to parse response" });
 }
 setRolling(false);
 }).catch(function () {
 setResult({ error: "Connection failed" });
 setRolling(false);
 });
 }

 return (
 <section className="cc-section cc-section--dice">
 <h2 className="cc-section__title">
 <span className="cc-glyph">&gt;</span> Test Roll
 </h2>
 <div className="cc-dice-controls">
 <div className="cc-field">
 <label className="cc-label">Attribute Die</label>
 <select className="cc-select" value={attrDie} onChange={function (e) { setAttrDie(e.target.value); }}>
 {ALL_DICE.map(function (d) { return <option key={d} value={d}>{d}</option>; })}
 </select>
 </div>
 <span className="cc-dice-vs">VS</span>
 <div className="cc-field">
 <label className="cc-label">Difficulty Die</label>
 <select className="cc-select" value={diffDie} onChange={function (e) { setDiffDie(e.target.value); }}>
 {ALL_DICE.map(function (d) { return <option key={d} value={d}>{d}</option>; })}
 </select>
 </div>
 <button className="cc-btn cc-btn--roll" onClick={handleRoll} disabled={rolling}>
 {rolling ? "Rolling..." : "⚄ Roll"}
 </button>
 </div>
 {result && !result.error && (
 <div className="cc-dice-result">
 <div className="cc-dice-result__row">
 <span className="cc-dice-result__label">Attribute Roll ({result.attributeDie}):</span>
 <span className="cc-dice-result__value">{result.attributeRoll}</span>
 </div>
 <div className="cc-dice-result__row">
 <span className="cc-dice-result__label">Difficulty Roll ({result.difficultyDie}):</span>
 <span className="cc-dice-result__value">{result.difficultyRoll}</span>
 </div>
 <div className="cc-dice-result__row">
 <span className="cc-dice-result__label">Difference:</span>
 <span className="cc-dice-result__value">{result.difference >= 0 ? "+" : ""}{result.difference}</span>
 </div>
 <div className={"cc-dice-result__outcome" + (result.success ? " cc-dice-result__outcome--success" : " cc-dice-result__outcome--failure")}>
 {result.description}
 </div>
 </div>
 )}
 {result && result.error && (
 <div className="cc-dice-result cc-dice-result--error">
 <span className="cc-error-msg">ERROR: {result.error}</span>
 </div>
 )}
 </section>
 );
}

function CharacterCreation() {
 var [name, setName] = useState("");
 var [handle, setHandle] = useState("");
 var [role, setRole] = useState("Solo");
 var [backstory, setBackstory] = useState("");
 var [allocation, setAllocation] = useState({
 Body: "d4", Reflexes: "d4", Tech: "d4",
 Cool: "d4", Intelligence: "d4", Willpower: "d4"
 });
 var [status, setStatus] = useState(null);
 var [saving, setSaving] = useState(false);

 var isValid = useCallback(function () {
 var hasName = name.trim().length > 0;
 var hasD8 = false;
 var hasD6 = false;
 ATTRIBUTES.forEach(function (a) {
 if (allocation[a] === "d8") hasD8 = true;
 if (allocation[a] === "d6") hasD6 = true;
 });
 return hasName && hasD8 && hasD6;
 }, [name, allocation]);

 function handleCreate() {
 if (!isValid()) return;
 setSaving(true);
 setStatus(null);
 callAjax("BlackLedgerCharacterCreation", "ajaxCreateCharacter", {
 sysparm_name: name.trim(),
 sysparm_handle: handle.trim(),
 sysparm_role: role,
 sysparm_backstory: backstory.trim(),
 sysparm_allocation: JSON.stringify(allocation)
 }).then(function (answer) {
 try {
 var resp = JSON.parse(answer);
 if (resp.success) {
 setStatus({ type: "success", message: "Character created: " + name.trim() });
 } else {
 setStatus({ type: "error", message: resp.message || "Creation failed" });
 }
 } catch (e) {
 setStatus({ type: "success", message: "Character registered in the ledger." });
 }
 setSaving(false);
 }).catch(function () {
 setStatus({ type: "error", message: "Network error — connection to ledger lost" });
 setSaving(false);
 });
 }

 return (
 <div className="cc-container">
 <header className="cc-header">
 <div className="cc-header__logo">BLACK LEDGER</div>
 <h1 className="cc-header__title">Character Creation Protocol</h1>
 <div className="cc-header__subtitle">// Initialize new operative record</div>
 </header>

 <CharacterInfo
 name={name} setName={setName}
 handle={handle} setHandle={setHandle}
 role={role} setRole={setRole}
 backstory={backstory} setBackstory={setBackstory}
 />

 <AttributeAllocator allocation={allocation} setAllocation={setAllocation} />

 <ValidationSummary allocation={allocation} name={name} />

 <div className="cc-actions">
 <button
 className={"cc-btn cc-btn--create" + (isValid() ? " cc-btn--ready" : "")}
 onClick={handleCreate}
 disabled={!isValid() || saving}
 >
 {saving ? "[ PROCESSING... ]" : "[ CREATE CHARACTER ]"}
 </button>
 {status && (
 <div className={"cc-status cc-status--" + status.type}>
 {status.message}
 </div>
 )}
 </div>

 <DiceRoller />

 <footer className="cc-footer">
 <span className="cc-footer__text">BLACK LEDGER SYSTEM v1.0 // SECURE CONNECTION</span>
 </footer>
 </div>
 );
}

ReactDOM.createRoot(document.getElementById("root")).render(<CharacterCreation />);
